V5F = ROOT / "kernels" / PROBLEM / "sonnet_v5f.py"
needs_cuda = pytest.mark.skipif(not torch.cuda.is_available(), reason="needs a CUDA GPU")


def _load(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    m = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(m)
    return m


@pytest.fixture(scope="module")
def mod():
    return _load("_measure_t1_v1", MEASURE)


@pytest.fixture(scope="module")
def v5f():
    return _load("_sonnet_v5f_for_t1", V5F)


# --------------------------------------------------------------------------------------------- CPU
def test_source_rules_and_in_sync_with_generator():
    src = MEASURE.read_text()
    compile(src, "measure_t1_v1.py", "exec")
    lines = src.splitlines()
    assert lines[0] == "# okc: problem=muse_decode_layer" and "MEASUREMENT-ONLY" in lines[1] and "NEVER submit" in lines[1]
    for banned in ("subprocess", "urllib", "requests", "socket", "os.system", ".item(", ".cpu(", "environ", "import os", ".tolist(", "from reference"):
        assert banned not in src.replace("problems/muse_decode_layer/reference.py", ""), banned
    from tools import gen_measure_t1_v1 as gen
    assert gen.build() == src, "regenerate: .venv/bin/python tools/gen_measure_t1_v1.py"
    assert "MEASUREMENT-ONLY" not in V5F.read_text() and "_t1_" not in V5F.read_text()


def test_claim_verdicts_are_at_the_top_of_the_header():
    src = MEASURE.read_text()
    head = src[:src.index("\n# --- the header below is sonnet_v5c")]       # v5f's own header follows the C37 one
    for tag in ("A1   TRUE in code, DORMANT", "A1b  TRUE", "A1c  TRUE", "A2   FALSE premise", "A2b  TRUE", "A3   TRUE in code", "A5   TRUE structure"):
        assert tag in head, tag
    assert "POOL_PS1_T1 is DROPPED" in head and "24,576 B" in head and "NEVER submit" in head.splitlines()[1]
    assert head.index("VERIFICATION of drafts/argon_C36") < head.index("Variants (module switches")


def test_kernel_fn_and_prepare_are_sonnet_v5f_verbatim():
    v5 = V5F.read_text().splitlines(keepends=True)
    src = MEASURE.read_text()
    assert "".join(v5[1:]).rstrip("\n") in src
    assert "def kernel_fn(data, state):\n    if HAVE_SGLANG:\n        return _kernel_sglang(data, state)\n    return _kernel_torch(data, state)" in src
    assert src.count("def kernel_fn(") == 1
    i = src.index("_t1_orig_prepare = prepare")
    assert "state = _t1_orig_prepare(weights)" in src[i:] and src[i:].rstrip().endswith("return state")


def _hunks(a, b):
    sm = difflib.SequenceMatcher(None, a, b, autojunk=False)
    return [op for op in sm.get_opcodes() if op[0] != "equal"]


def test_t1_kernel_is_v5fs_layer_with_four_marked_edits(mod, v5f):
    src = MEASURE.read_text()
    tree = ast.parse(src)
    fn = {n.name: "\n".join(src.splitlines()[n.lineno - 1:n.end_lineno]) for n in tree.body if isinstance(n, ast.FunctionDef)}
    v5 = V5F.read_text()
    t5 = ast.parse(v5)
    o = next(n for n in t5.body if isinstance(n, ast.FunctionDef) and n.name == "_kernel_sglang")
    orig = "\n".join(v5.splitlines()[o.lineno - 1:o.end_lineno])
    ops = _hunks(orig.splitlines(), fn["_t1_kernel"].splitlines())
    assert len(ops) == 5, ops           # def line, `pre = None`, the route_side block, the record_stream tuple, the experts call
    new = fn["_t1_kernel"]
    assert "def _t1_kernel(data, state, V):" in new and "pre = _t1_route(topk_ids, data[\"local_start\"], state, V)" in new and "+ (pre or ())" in new
    assert "_t1_experts(" in new and "local_ids=local_ids, V=V, pre=pre)" in new
    assert new.count("_smallm_live") == 1 and orig.count("_experts(") == 1


def test_patched_device_source_differs_in_three_hunks(mod, v5f):
    a, b = v5f._SMALLM_DEVICE_SRC.splitlines(), mod._t1_device_src().splitlines()
    ops = _hunks(a, b)
    assert len(ops) == 3, ops
    new = "\n".join(b)
    assert "int act_shift, int trig_late) {" in new and "if (FUSE && !trig_late) pdl_trigger();" in new and "if (FUSE && trig_late) pdl_trigger();" in new
    assert new.count("pdl_trigger()") == v5f._SMALLM_DEVICE_SRC.count("pdl_trigger()") + 1      # the late trigger is the only new call
    # the host source: one launch path, checked CUDA calls, rows 8 / 16 only, three instantiations
    h = mod._T1_HOST_SRC
    assert "T1_CK(cudaFuncSetAttribute" in h and "rows == 8 || rows == 16" in h and "T1_CASE(true, 8) T1_CASE(false, 4) T1_CASE(false, 8)" in h and "const cudaError_t e = cudaLaunchKernelExC" in h
    assert "&i_tl}" in h and "int64_t rows, int64_t trig_late, bool fuse" in mod._T1_CPP_SRC


def test_facts_behind_the_verdicts(mod, v5f):
    """The verifications of the header as assertions (they fail loudly if v5f changes under the study)."""
    assert v5f.SMALLM_CFG[0] == (1, 8, 2, 2, 4, 2, 6)                      # A1: nz1 = 2 at M = 1, nw1 = 8 (not 4)
    cfg = v5f.smallm_cfg(1)
    assert (cfg["nw1"], cfg["ks1"], cfg["nz1"], cfg["nw2"], cfg["nz2"]) == (8, 2, 2, 4, 6)
    dev = v5f._SMALLM_DEVICE_SRC
    k = dev[dev.index("w4_smallm_kernel(const uint4*"):dev.index("smallm_route_kernel(const int*")]
    assert "if (FUSE) pdl_trigger();" in k and k.index("if (FUSE) pdl_trigger();") < k.index("k_loop<1>")                                 # A1b: before the K-loop
    assert "for (int z = blockIdx.z; z < n_act; z += gridDim.z)" in k and "const int nrows = me > 8 ? 16 : 8;" in k                    # A1: serial z loop; A1c: 8 rows staged at M <= 8
    host = v5f._SMALLM_HOST_SRC
    assert "const size_t smem = 1024 + (size_t)16 * (Kc + 8) * 2;" in host                                                              # A1c: 16 rows allocated at every M
    assert (1024 + 16 * (2048 + 8) * 2) == 66816 and (1024 + 8 * (2048 + 8) * 2) == 33920                                              # 66.8 KB -> 33.9 KB
    assert v5f.POOLER_PS1_MIN_TOKENS == 2 and v5f._pooler_cfg(1) == (32, 512, 1, 4, 4) and v5f._pooler_cfg(2) == v5f.POOLER_PS1_CFG    # A2: ps1 from T = 2
    assert v5f.S3_PDL is False and v5f.S2_FUSED_ROUTING is False and v5f.ROUTER_FIX_TOKENS == 1                                       # the board's T = 1 router is RPAR, no Triton PDL
    rt = dev[dev.index("smallm_route_kernel(const int*"):]
    assert "const int* __restrict__ lo" in rt[:300]                                                                                      # A2b: ids + local_start only
    src = V5F.read_text()
    assert "def smallm_route(torch::Tensor ids, torch::Tensor local_ids, torch::Tensor tab, torch::Tensor lo, int64_t nloc)" in src.replace("void smallm_route", "def smallm_route", 1) or "void smallm_route(torch::Tensor ids" in src


def test_variant_switches_and_scopes(mod, v5f):
    V = {v.name: v for v in mod._T1_SINGLES}
    assert [v.name for v in mod._T1_SINGLES] == ["base", "nz8", "trig_early", "trig_late", "rows2", "route_side"]
    assert not V["base"].custom and V["nz8"].custom and not V["nz8"].ext2 and V["trig_late"].ext2 and V["rows2"].ext2 and V["trig_early"].ext2 and V["route_side"].custom and not V["route_side"].ext2
    assert mod._t1_cfg(1, V["nz8"])["nz1"] == 8 and mod._t1_cfg(16, V["nz8"])["nz1"] == v5f.smallm_cfg(16)["nz1"] and mod._t1_cfg(1, V["base"]) == v5f.smallm_cfg(1)
    assert mod._t1_rows(1, V["rows2"]) == 8 and mod._t1_rows(8, V["rows2"]) == 8 and mod._t1_rows(9, V["rows2"]) == 16 and mod._t1_rows(16, V["rows2"]) == 16 and mod._t1_rows(1, V["base"]) == 16
    c, of = mod._t1_combo(("nz8", "rows2"))
    assert c.nz1 == 8 and c.rows2 and not c.trig_late and not c.route_side and c.ext2 and of == ("nz8", "rows2")
    c, of = mod._t1_combo(())
    assert c.nz1 == 8 and c.rows2 and c.trig_late and c.route_side and of == ("nz8", "trig_late", "rows2", "route_side")
    # every smem the variants launch fits sm_90's 227 KB and the kernels' 98304 B attribute; the rows are the kernel's staged rows
    for kc in (2048, 1024):
        assert 1024 + 16 * (kc + 8) * 2 <= 98304
    names = [n for n, _kw in mod._T1_SHAPES]
    assert names == ["dec1s", "dec1f", "dec16s"] and mod._T1_SEEDS == (11, 12, 13) and mod._T1_BUDGET_S <= 270 and mod._T1_MAX_BYTES <= 14000


def _fake_res(mod, gains, ovh=4.0, base=(100.0, 120.0, 200.0)):
    """results dict: base us per shape (the same for every seed) and per-variant gains {name: (g_dec1s, g_dec1f, g_dec16s)} in us."""
    res = {"ovh": ovh, "l": {}, "bw": {}, "E": {}, "skipped": [], "combo_of": ()}
    for i, (shape, _kw) in enumerate(mod._T1_SHAPES):
        for s in mod._T1_SEEDS:
            res["E"][(shape, s)] = 2
            res["l"][(shape, s, "base")] = base[i] + 0.1 * (s - 12)
            res["l"][(shape, s, "base2")] = base[i] + 0.1 * (s - 12) + 0.05
            res["bw"][(shape, s, "base")] = "OK"
            for n, g in gains.items():
                res["l"][(shape, s, n)] = base[i] + 0.1 * (s - 12) - g[i]
                res["bw"][(shape, s, n)] = "OK"
    return res


def test_winners_rule_and_report(mod):
    gains = {"nz8": (0.1, 0.0, 0.0), "trig_early": (0.0, 0.0, 0.0), "trig_late": (3.0, 3.0, 0.5), "rows2": (2.6, 0.5, -0.5), "route_side": (1.6, 1.6, 0.0), "combo": (4.5, 3.5, 1.0)}
    res = _fake_res(mod, gains)
    _t, wins = mod._t1_winners(res, min_us=mod._T1_COMBO_US)
    assert set(wins) == {"trig_late", "rows2", "route_side", "combo"}                  # >= 1 us weighted at T = 1, 16: rows2 loses 0.25 % (<= 1 %)
    _t, wins2 = mod._t1_winners(res, min_us=mod._T1_WIN_US)
    assert set(wins2) == {"trig_late", "rows2", "combo"}                               # route_side: 1.6 us < 2
    bad = dict(gains, trig_late=(3.0, 3.0, -4.0))                                       # -4 us of 200 = 2 % at decode 16: not a winner
    assert "trig_late" not in mod._t1_winners(_fake_res(mod, bad), min_us=1.0)[1]
    res["bw"][("dec1s", 11, "rows2")] = "DIFF"
    assert "rows2" not in mod._t1_winners(res, min_us=1.0)[1]                           # never a winner when not bitwise
    res["bw"][("dec1s", 11, "rows2")] = "OK"
    out = mod._t1_render(res, "gpu=fake", 0.0, 12.0)
    lines = out.splitlines()
    assert lines[0].startswith("MEAS-T1 gpu=fake ovh=4.0us") and "E(dec1s)=2/2/2" in lines[0]
    assert all(l.startswith("S t1") for l in lines[1:1 + 8])                            # S lines first: base, nz8, trig_early, trig_late, rows2, route_side, combo, base2
    s_trig = next(l for l in lines if l.startswith("S t1 trig_late"))
    assert re.search(r"dec1s=93\.0us x1\.031 dec1f=113\.0us x1\.026 dec16s=195\.5us x1\.003 \| bw=OK$", s_trig), s_trig        # 100 - 3 gain - 4 overhead; 120 - 3 - 4; 200 - 0.5 - 4
    d = next(l for l in lines if l.startswith("D t1"))
    assert "winners (>= 2us weighted at T=1, T=16 regression <= 1%): trig_late, rows2, combo" in d and "noise(base2-base dec1s)=+0.05us" in d
    assert lines[-1].startswith("MEAS-T1 done 12s") and len(out.encode()) < mod._T1_MAX_BYTES
    assert all(l.startswith(("S ", "B ", "D ", "N ", "MEAS-T1")) for l in lines)


class _FakeEnv:
    def __init__(self, gains, bw_diff=()):
        self.gains, self.bw_diff, self.t, self.runs = gains, set(bw_diff), 0.0, []
        self.base = {"dec1s": 100.0, "dec1f": 120.0, "dec16s": 200.0}

    def available(self):
        return True

    def clock(self):
        self.t += 0.01
        return self.t

    def banner(self):
        return "gpu=fake"

    def overhead(self):
        return 4.0

    def case(self, shape, seed):
        return {"shape": shape, "seed": seed, "E": 2}

    def run(self, ctx, V):
        self.runs.append((ctx["shape"], V.name))
        return (ctx, V)

    def same(self, ctx, out):
        return out[1].name not in self.bw_diff

    def graph_time(self, fn, reps=None):
        ctx, V = fn()
        return self.base[ctx["shape"]] + 4.0 - self.gains.get(V.name, (0, 0, 0))[[s for s, _ in sorted({"dec1s": 0, "dec1f": 1, "dec16s": 2}.items(), key=lambda kv: kv[1])].index(ctx["shape"])]

    def release(self):
        pass


def test_study_control_flow_with_a_fake_env(mod, monkeypatch, capsys):
    monkeypatch.setitem(mod._T1_EXT, "ext", object())
    monkeypatch.setitem(mod._T1_EXT, "err", None)
    gains = {"trig_late": (3.0, 3.0, 0.0), "rows2": (0.4, 0.0, 0.0), "combo": (3.5, 3.0, 0.0)}
    env = _FakeEnv(gains)
    res = mod._t1_study({}, env=env)
    out = capsys.readouterr().out
    assert res["combo_of"] == ("trig_late",)                                      # only trig_late gains >= 1 us at T = 1
    assert {n for (_s, _sd, n) in res["l"]} == {"base", "nz8", "trig_early", "trig_late", "rows2", "route_side", "base2", "combo"}
    assert len(out.encode()) < mod._T1_MAX_BYTES and out.splitlines()[0].startswith("MEAS-T1 gpu=fake") and "MEAS-T1 done" in out
    assert "winners (>= 2us weighted at T=1, T=16 regression <= 1%): trig_late, combo" in out
    assert "skipped" not in out
    # a variant that is not bitwise is flagged and is never a winner
    env = _FakeEnv(gains, bw_diff=("trig_late",))
    res = mod._t1_study({}, env=env)
    out = capsys.readouterr().out
    assert re.search(r"^S t1 trig_late\s+\|.*bw=DIFF$", out, re.M) and "winners (>= 2us weighted at T=1, T=16 regression <= 1%): none" in out.replace("combo", "") or "trig_late," not in out.split("D t1")[1].split("|")[0]


def test_study_drops_variants_that_do_not_fit_the_budget_and_survives_no_ext(mod, monkeypatch, capsys):
    monkeypatch.setitem(mod._T1_EXT, "ext", None)
    monkeypatch.setitem(mod._T1_EXT, "err", "boom")
    env = _FakeEnv({})
    res = mod._t1_study({}, env=env)
    out = capsys.readouterr().out
    names = {n for (_s, _sd, n) in res["l"]}
    assert names == {"base", "nz8", "route_side", "base2"} and any("no-ext" in s for s in res["skipped"]) and "combo:no-ext" in res["skipped"] and "MEAS-T1 done" in out        # the patched-extension variants are dropped
    monkeypatch.setitem(mod._T1_EXT, "ext", object())
    monkeypatch.setitem(mod._T1_EXT, "err", None)
    env = _FakeEnv({})
    env.clock = lambda: (setattr(env, "t", env.t + 80.0) or env.t)
    mod._t1_study({}, env=env)
    out = capsys.readouterr().out
    assert "MEAS-T1 done" in out and "skipped:" in out and len(out.encode()) < mod._T1_MAX_BYTES


def test_prepare_wrapper_never_breaks_prepare(mod, monkeypatch):
    monkeypatch.setattr(mod, "_t1_orig_prepare", lambda w: {"state": 1})
    monkeypatch.setattr(mod, "_t1_study", lambda *a, **k: (_ for _ in ()).throw(RuntimeError("study broke")))
