# --------------------------------------------------------------------------------------------- GPU: NVRTC on the dev card
@pytest.fixture(scope="module")
def nv():
    if not torch.cuda.is_available():
        pytest.skip("needs a CUDA GPU")
    nv = pytest.importorskip("nvrtc_smallm")
    if not nv.HAVE_NVRTC:
        pytest.skip("cuda-python / NVRTC not available")
    return nv


T1_NAMES = ["w4_smallm_kernel<true,8>", "w4_smallm_kernel<false,4>", "w4_smallm_kernel<false,8>", "smallm_route_kernel"]


def _t1_ext_factory(nv):
    """An NVRTC stand-in for the patched extension (same call signature as the host function smallm_gemm_t1)."""
    from cuda.bindings import driver as cu

    class Ext(nv.NvrtcExt):
        def __init__(self, src):
            import torch as _t
            _t.zeros(1, device="cuda")
            major, minor = _t.cuda.get_device_capability()
            self.arch = f"sm_{major}{minor}"
            cubin, self.lowered = nv.compile_device(src, self.arch, names=T1_NAMES)
            self.module = nv._chk(cu.cuModuleLoadData(cubin))
            self.fn = {n: nv._chk(cu.cuModuleGetFunction(self.module, low.encode())) for n, low in self.lowered.items()}
            self.launches = []

        def smallm_gemm_t1(self, wq, sq, gs, lut, act, tab, part, cnt, out, G, NIT, K, KS, nz, out_stride, act_shift, nw, rows, trig_late, fuse):
            kc = K // KS
            smem = 1024 + rows * (kc + 8) * 2
            assert rows in (8, 16)
            fn = self.fn[f"w4_smallm_kernel<{'true' if fuse else 'false'},{nw}>"]
            if smem > 48 * 1024:
                nv._chk(cu.cuFuncSetAttribute(fn, cu.CUfunction_attribute.CU_FUNC_ATTRIBUTE_MAX_DYNAMIC_SHARED_SIZE_BYTES, smem))
            self.launches.append((fuse, nw, nz, rows, trig_late, smem))
            self._launch(fn, (G // nw, KS, nz), (nw * 32, 1, 1), smem, [wq, sq, gs, lut, act, tab, part, cnt, out, G, NIT, K, KS, out_stride, act_shift, trig_late])

    return Ext


DEV_CFG = ((16, 8, 4, 8, 8, 4, 8),)       # (largest M, nw1, ks1, nz1, nw2, ks2, nz2): 64 KB of smem on the dev card -> K slice 1024


@pytest.fixture(scope="module")
def dev(mod, v5f, nv):
    from nvfp4 import random_weights

    g = torch.Generator(device="cuda").manual_seed(4242)
    w13, w13_sf, gs13 = random_weights(8192, 4096, generator=g, device="cuda", leading=(32,))
    w2, w2_sf, gs2 = random_weights(4096, 4096, generator=g, device="cuda", leading=(32,))
    w = {"w13": w13, "w13_sf": w13_sf, "w13_gs": gs13.expand(32).contiguous(), "w2": w2, "w2_sf": w2_sf, "w2_gs": gs2.expand(32).contiguous()}
    for m_ in (v5f, mod):
        m_.SMALLM_CFG = DEV_CFG
    sm = mod.prepare_smallm(w, ext=nv.NvrtcExt(mod._SMALLM_DEVICE_SRC))
    ext2 = _t1_ext_factory(nv)(mod._t1_device_src())
    mod._T1_EXT["ext"] = ext2
    yield sm, ext2
    del sm, w, ext2
    mod._T1_EXT["ext"] = None
    torch.cuda.empty_cache()


def _inputs(m, seed):
    g = torch.Generator(device="cuda").manual_seed(seed)
    x = torch.randn((m, 4096), generator=g, device="cuda").to(torch.bfloat16)
    ids = torch.randint(0, 40, (m, 8), generator=g, device="cuda", dtype=torch.int32)        # 32 local ids [0, 32) and some remote ones
    return x, ids


def _live(y, lids):
    return y.reshape(-1, y.shape[-1]).view(torch.int16)[lids.reshape(-1) >= 0]


@needs_cuda
@pytest.mark.parametrize("m", [1, 4, 8, 16])
@pytest.mark.parametrize("name", ["base", "nz8", "trig_early", "trig_late", "rows2", "route_side", "combo"])
def test_patched_kernels_are_bitwise_v5f(mod, v5f, dev, m, name):
    """nz1 8 / 8 staged rows / trig_late (a no-op below sm_90) / the route done in advance: the expert outputs equal v5f's smallm_experts bit for bit (dev table: K slice 1024)."""
    sm, ext2 = dev
    V = {v.name: v for v in mod._T1_SINGLES}.get(name) or mod._t1_combo(("nz8", "trig_late", "rows2", "route_side"))[0]
    start = torch.zeros(1, dtype=torch.int32, device="cuda")
    for seed in (1, 2):
        x, ids = _inputs(m, 100 * m + seed)
        y0, l0 = v5f.smallm_experts(x, ids, sm, start, 32, v5f.smallm_cfg(m))
        pre = mod._t1_route(ids, start, {"smallm": sm}, V) if V.route_side else None
        y1, l1 = mod._t1_smallm_experts(x, ids, sm, start, 32, mod._t1_cfg(m, V), V, pre, ext2 if V.ext2 else None)
        torch.cuda.synchronize()
        assert torch.equal(l0, l1) and torch.equal(_live(y0, l0), _live(y1, l1)), (m, name, seed)
        assert int(sm["cnt"].abs().sum()) == 0
    if V.ext2:
        f1, f2 = ext2.launches[-2], ext2.launches[-1]
        assert f1[:2] == (True, 8) and f2[0] is False and f1[3] == f2[3] == (8 if (V.rows2 and m <= 8) else 16) and f1[4] == f2[4] == int(V.trig_late)
        assert f1[5] == 1024 + f1[3] * (1024 + 8) * 2
    if name == "nz8" and m == 1:
        assert max(1, min(8, m * 8)) == 8


@needs_cuda
def test_route_on_a_side_stream_inside_a_two_stream_graph(mod, v5f, dev):
    """ROUTE_SIDE's topology: the route on the side stream (after the 'routing'), the main stream joins, GEMMs on main: captured as a graph, replayed on fresh ids, bitwise v5f."""
    sm, ext2 = dev
    V = {v.name: v for v in mod._T1_SINGLES}["route_side"]
    start = torch.zeros(1, dtype=torch.int32, device="cuda")
    side = torch.cuda.Stream()
    x, ids = _inputs(1, 77)
    state = {"smallm": sm}

    def pipeline():
        main = torch.cuda.current_stream()
        side.wait_stream(main)
        with torch.cuda.stream(side):
            pre = mod._t1_route(ids, start, state, V)
        main.wait_stream(side)
        return mod._t1_smallm_experts(x, ids, sm, start, 32, mod._t1_cfg(1, V), V, pre, None)

    s = torch.cuda.Stream()
    s.wait_stream(torch.cuda.current_stream())
    with torch.cuda.stream(s):
        pipeline()
    torch.cuda.current_stream().wait_stream(s)
    g = torch.cuda.CUDAGraph()
    with torch.cuda.graph(g):
        y1, l1 = pipeline()
    for seed in (78, 79, 80):
        x2, ids2 = _inputs(1, seed)
        x.copy_(x2)
        ids.copy_(ids2)
        g.replay()
        torch.cuda.synchronize()
        y0, l0 = v5f.smallm_experts(x, ids, sm, start, 32, v5f.smallm_cfg(1))
        assert torch.equal(l0, l1) and torch.equal(_live(y0, l0), _live(y1, l1)), seed
    assert int(sm["cnt"].abs().sum()) == 0


