# --------------------------------------------------------------------------------------------- sm_90 assembly + the claim A2 compile (LAST: ptx_audit patches the device capability)
def _ptxas(nv, src, name):
    from cuda.bindings import nvrtc

    prog = nv._chk(nvrtc.nvrtcCreateProgram((src + f"\n__device__ long long t1_nonce = {time.time_ns()}LL;\n").encode(), b"k.cu", 0, [], []))
    nv._chk(nvrtc.nvrtcAddNameExpression(prog, name.encode()))
    opts = [b"--gpu-architecture=sm_90", b"-std=c++17", b"-default-device", b"--ptxas-options=-v"]
    res = nvrtc.nvrtcCompileProgram(prog, len(opts), opts)
    n = nv._chk(nvrtc.nvrtcGetProgramLogSize(prog))
    log = b" " * n
    nv._chk(nvrtc.nvrtcGetProgramLog(prog, log))
    assert res[0] == nvrtc.nvrtcResult.NVRTC_SUCCESS, log.decode(errors="replace")[:1500]
    body = re.search(r"Compiling entry function '(_Z[^']*)' for 'sm_90'(.*?)Compile time", log.decode(errors="replace"), re.S).group(2)
    regs = int(re.search(r"Used (\d+) registers", body).group(1))
    sp = re.search(r"(\d+) bytes spill stores, (\d+) bytes spill loads", body)
    return regs, int(sp.group(1)), int(sp.group(2))


@needs_cuda
@pytest.mark.parametrize("name", ["w4_smallm_kernel<true,8>", "w4_smallm_kernel<false,4>", "w4_smallm_kernel<false,8>"])
def test_patched_source_assembles_for_sm90_with_the_trigger_after_the_k_loop(mod, v5f, nv, name):
    r0 = _ptxas(nv, v5f._SMALLM_DEVICE_SRC, name)
    r1 = _ptxas(nv, mod._t1_device_src(), name)
    assert r1[1:] == (0, 0) and r0[1:] == (0, 0) and r1[0] <= r0[0] + 2, (name, r0, r1)          # the extra argument costs no registers / spills
    ptx, low = nv.compile_device(mod._t1_device_src(), "compute_90", want="ptx", names=[name])
    ptx = ptx.decode(errors="replace")
    k = ptx[ptx.index(".entry " + low[name].rstrip("\x00")):]
    nxt = k.find(".visible .entry", 10)
    k = k if nxt < 0 else k[:nxt]
    n_trig = k.count("griddepcontrol.launch_dependents")
    if "true" in name:
        assert n_trig >= 2                         # one guarded before the K-loop (trig_late == 0), one after it (trig_late == 1) (the compiler may duplicate the tail)
        assert k.index("griddepcontrol.launch_dependents") < k.index("mma.sync")                      # the early one
        assert k.rindex("griddepcontrol.launch_dependents") > k.index("mma.sync")                     # the late one follows the first mma of the K-loop
    else:
        assert n_trig == 0                         # GEMM2 never triggers
    assert k.count("griddepcontrol.wait") == 1


@needs_cuda
def test_claim_a2_router_fix_kernel_smem_for_sm90a(v5f):
    """Claim A2 (Argon: _router_fix_kernel ~140 KB of smem, so it cannot co-reside with the 147 KB pooler at T = 1): compiled for sm_90a it needs 24,576 B."""
    from tools import ptx_audit as pa

    dev = "cuda"
    st = {"router_hi": torch.zeros(256, 8192, dtype=torch.bfloat16, device=dev), "router_lo": torch.zeros(256, 8192, dtype=torch.bfloat16, device=dev),
          "rfix_part": torch.zeros(64, 16, 256, dtype=torch.float32, device=dev), "rfix_done": torch.zeros(64, dtype=torch.int32, device=dev)}
    x = torch.zeros(1, 8192, dtype=torch.float32, device=dev)
    with pa.Capture() as cap:
        v5f._router_fix(x, None, st)
    recs = [r for r in cap.records if r["name"] == "_router_fix_kernel"]
    assert recs
    c = pa.compile_record(recs[0])
    assert c["smem"] == 24576 and c["spills"] == 0, c
    assert 147456 + c["smem"] <= 227 * 1024        # pooler (T = 1 config) + router CTAs fit one SM: they co-reside
